-- (1) target ton per afd x tahun tanam x status (target harian per blok x status HS bulan itu); tgt_a = Jan..bulan-1, tgt_m = bulan laporan
WITH hs AS (SELECT DECODE(KODE_BA,'2122','2131',KODE_BA) ba,KODE_AFD afd,KODE_BLOK blok,DATE_TRUNC('month',BULAN)::DATE mo,MAX(COALESCE(NULLIF(TAHUN_TANAM,''),'?')) thn,MAX(IFF(UPPER(MATURITY_STATUS) LIKE 'TM%','TM','TBM')) kind FROM PRD_DB_INTEGRATION.INT_PANEN.INT_HEKTAR_BLOK WHERE KODE_BA IN ('2121','2124','2131','2122') AND BULAN>='2026-01-01' AND BULAN<'2026-10-01' GROUP BY 1,2,3,4),
t AS (SELECT DECODE(KODE_BA,'2122','2131',KODE_BA) ba,KODE_AFD afd,KODE_BLOK blok,DATE_TRUNC('month',TANGGAL_DATA)::DATE mo,SUM(TON_TARGET) ton FROM PRD_DB_INTEGRATION.INT_PANEN.INT_PANEN_HARIAN_TARGET WHERE KODE_BA IN ('2121','2124','2131','2122') AND TANGGAL_DATA>='2026-01-01' AND TANGGAL_DATA<'2026-10-01' GROUP BY 1,2,3,4)
SELECT h.ba,h.afd,h.thn,h.kind,ROUND(SUM(IFF(t.mo<'2026-09-01',t.ton,0)),2) tgt_a,ROUND(SUM(IFF(t.mo='2026-09-01',t.ton,0)),2) tgt_m FROM t JOIN hs h ON h.ba=t.ba AND h.afd=t.afd AND h.blok=t.blok AND h.mo=t.mo GROUP BY 1,2,3,4 ORDER BY 1,2,3,4;
-- (2) BBC Jan-Jun (YTD_TON_BBC terakhir per blok sampai 30 Jun) per afd x tahun tanam; Jul-Sep dari file SAP (alloc_file.py)
WITH l AS (SELECT DECODE(KODE_BA,'2122','2131',KODE_BA) ba,KODE_AFD afd,KODE_BLOK blok,YTD_TON_BBC y FROM PRD_DB_INTEGRATION.INT_PANEN.INT_PENCAPAIAN_PRODUKSI_PANEN WHERE KODE_BA IN ('2121','2124','2131','2122') AND TANGGAL_PANEN>='2026-01-01' AND TANGGAL_PANEN<='2026-06-30' QUALIFY ROW_NUMBER() OVER (PARTITION BY KODE_BA,KODE_AFD,KODE_BLOK ORDER BY TANGGAL_PANEN DESC)=1),
hs AS (SELECT DECODE(KODE_BA,'2122','2131',KODE_BA) ba,KODE_AFD afd,KODE_BLOK blok,MAX(COALESCE(NULLIF(TAHUN_TANAM,''),'?')) thn FROM PRD_DB_INTEGRATION.INT_PANEN.INT_HEKTAR_BLOK WHERE DATE_TRUNC('month',BULAN)='2026-06-01' GROUP BY 1,2,3)
SELECT l.ba,l.afd,COALESCE(h.thn,'?') thn,ROUND(SUM(l.y),2) bbc_h1 FROM l LEFT JOIN hs h ON h.ba=l.ba AND h.afd=l.afd AND h.blok=l.blok GROUP BY 1,2,3 ORDER BY 1,2,3;
